providers.source:
const OPENCODE_GO_USAGE_URL = "https://opencode.ai/zen/go/v1/usage";

function main(qb) {
  logStep(qb, "info", "provider.start", "OpenCode Go provider started");
  const apiKey = qb.env.get("OPENCODE_GO_API_KEY").trim();
  if (!apiKey) {
    throw new Error("OpenCode Go API key is required. Create one in the OpenCode Console and paste it into the provider setup form.");
  }
  logStep(qb, "info", "auth.loaded", "OpenCode Go API key loaded");

  const raw = fetchOpenCodeGoUsage(qb, apiKey);
  const usage = usagePayload(raw);
  if (!usage) {
    throw new Error("OpenCode Go did not return subscription usage. Make sure the API key belongs to an account with an active Go subscription.");
  }

  const nowMs = Date.now();
  const windows = [];
  pushWindow(windows, "5h", "5h", usage, ["rolling", "rollingUsage"], nowMs);
  pushWindow(windows, "weekly", "Weekly limit", usage, ["weekly", "weeklyUsage"], nowMs);
  pushWindow(windows, "monthly", "Monthly limit", usage, ["monthly", "monthlyUsage"], nowMs);

  logStep(qb, windows.length > 0 ? "info" : "warn", "snapshot.ready", "OpenCode Go snapshot ready", {
    status: windows.length > 0 ? "ok" : "warning",
    windowCount: windows.length
  });
  return {
    status: windows.length > 0 ? "ok" : "warning",
    updatedAt: qb.now(),
    windows,
    metadata: metadataFrom(raw, usage)
  };
}

function fetchOpenCodeGoUsage(qb, apiKey) {
  logStep(qb, "info", "usage.request.start", "OpenCode Go usage request started");
  const response = qb.http.request(OPENCODE_GO_USAGE_URL, {
    headers: {
      Authorization: `Bearer ${apiKey}`,
      Accept: "application/json",
      "User-Agent": "QuotaBarWin/1.7"
    }
  });
  logStep(qb, response.ok ? "info" : "warn", "usage.response", "OpenCode Go usage response received", {
    status: response.status,
    bodyBytes: response.body.length
  });
  if (response.status === 401) {
    throw new Error("OpenCode Go rejected the API key (HTTP 401). Check the key or create a new one in the OpenCode Console.");
  }
  if (response.status === 403) {
    throw new Error("OpenCode Go denied access to usage (HTTP 403). The key may lack the Usage permission or the account may not have a Go subscription.");
  }
  if (!response.ok) {
    throw new Error(`OpenCode Go usage API returned ${response.status}: ${response.body.slice(0, 160)}`);
  }
  return JSON.parse(response.body);
}

function usagePayload(raw) {
  if (!raw || typeof raw !== "object") return null;
  if (raw.usage && typeof raw.usage === "object") return raw.usage;
  if (raw.data && typeof raw.data === "object" && raw.data.usage && typeof raw.data.usage === "object") {
    return raw.data.usage;
  }
  return null;
}

function pushWindow(windows, id, label, usage, names, nowMs) {
  const source = firstWindow(usage, names);
  if (!source) return;
  const percent = firstNumber(source, ["percent", "usagePercent"]);
  if (percent === null) return;
  const usedPercent = clamp(percent, 0, 100);
  windows.push({
    id,
    label,
    used: null,
    limit: null,
    unit: "percent",
    usedPercent,
    remainingPercent: Math.max(0, 100 - usedPercent),
    resetAt: resetAtFrom(source, nowMs),
    resetText: null,
    confidence: "exact"
  });
}

function firstWindow(usage, names) {
  for (const name of names) {
    const value = usage[name];
    if (value && typeof value === "object") return value;
  }
  if (Array.isArray(usage.windows)) {
    for (const entry of usage.windows) {
      if (!entry || typeof entry !== "object") continue;
      const key = String(entry.name || entry.id || "").toLowerCase();
      if (names.indexOf(key) !== -1) return entry;
    }
  }
  return null;
}

function resetAtFrom(source, nowMs) {
  const resetsAt = source.resetsAt;
  if (typeof resetsAt === "string" && resetsAt.trim() !== "") {
    const parsed = Date.parse(resetsAt);
    if (Number.isFinite(parsed)) return new Date(parsed).toISOString();
  }
  const resetInSec = firstNumber(source, ["resetInSec", "resetAfterSeconds"]);
  if (resetInSec !== null && resetInSec >= 0) {
    return new Date(nowMs + resetInSec * 1000).toISOString();
  }
  return null;
}

function metadataFrom(raw, usage) {
  const billing = raw && raw.billing && typeof raw.billing === "object" ? raw.billing : {};
  const topLevelBalance = booleanOrNull(raw && raw.useBalance);
  return {
    plan: stringOrNull(raw && raw.plan) || stringOrNull(billing.subscriptionPlan) || null,
    useBalance: topLevelBalance !== null ? topLevelBalance : booleanOrNull(usage && usage.useBalance)
  };
}

function firstNumber(source, keys) {
  for (const key of keys) {
    const value = numberOrNull(source[key]);
    if (value !== null) return value;
  }
  return null;
}
function numberOrNull(value) {
  if (value === null || value === undefined || value === "") return null;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
}
function booleanOrNull(value) {
  return typeof value === "boolean" ? value : null;
}
function stringOrNull(value) {
  return typeof value === "string" && value.trim() !== "" ? value.trim() : null;
}
function clamp(value, min, max) {
  return Math.min(Math.max(value, min), max);
}
function logStep(qb, level, stage, message, fields) {
  qb.log(Object.assign({ level, stage, message }, fields || {}));
}

function main(qb) {
  logStep(qb, "info", "provider.start", "DeepSeek provider started");
  const raw = fetchDeepSeekBalance(qb);
  const requestedCurrency = textOrNull(qb.env.getOptional("DEEPSEEK_BALANCE_CURRENCY"));
  const balances = (raw.balance_infos || []).filter(
    (balance) => !requestedCurrency || balance.currency === requestedCurrency
  );
  if (requestedCurrency && balances.length === 0) {
    throw new Error(`DeepSeek balance did not include currency ${requestedCurrency}`);
  }
  const windows = balances.map((balance) => balanceToWindow(qb, balance));
  const warningWindows = windows.filter(
    (window) => window.warningRemaining !== null && window.remaining !== null
      && window.remaining <= window.warningRemaining
  );
  const status = raw.is_available === false || warningWindows.length > 0 ? "warning" : "ok";
  logStep(qb, "info", "snapshot.ready", "DeepSeek snapshot ready", {
    status,
    windowCount: windows.length,
    warningWindowCount: warningWindows.length
  });
  const balancesMetadata = {};
  for (const balance of balances) {
    balancesMetadata[balance.currency] = {
      totalBalance: numberOrNull(balance.total_balance),
      grantedBalance: numberOrNull(balance.granted_balance),
      toppedUpBalance: numberOrNull(balance.topped_up_balance)
    };
  }
  return {
    status,
    updatedAt: qb.now(),
    windows,
    diagnostics: raw.is_available === false || warningWindows.length > 0 ? {
      checkedAt: qb.now(),
      messages: (raw.is_available === false ? ["DeepSeek account is not available"] : []).concat(
        warningWindows.map(
          (window) => `${window.label} is at ${formatMoney(window.remaining, window.unit)}; warning ${formatMoney(window.warningRemaining, window.unit)}`
        )
      )
    } : null,
    metadata: {
      isAvailable: raw.is_available === undefined ? null : raw.is_available,
      currency: requestedCurrency,
      balances: balancesMetadata
    }
  };
}

function fetchDeepSeekBalance(qb) {
  const token = qb.env.get("DEEPSEEK_API_KEY");
  logStep(qb, "info", "http.request.start", "Requesting DeepSeek balance", {
    endpoint: "api.deepseek.com/user/balance"
  });
  const response = qb.http.request("https://api.deepseek.com/user/balance", {
    headers: { Accept: "application/json", Authorization: `Bearer ${token}` }
  });
  logStep(qb, response.ok ? "info" : "warn", "http.response", "DeepSeek balance response received", {
    status: response.status
  });
  if (!response.ok) throw new Error(`DeepSeek balance request failed with ${response.status}`);
  return JSON.parse(response.body);
}

function logStep(qb, level, stage, message, fields) {
  qb.log(Object.assign({ level, stage, message }, fields || {}));
}

function balanceToWindow(qb, balance) {
  const currency = String(balance.currency || "unknown").trim() || "unknown";
  const remaining = numberOrNull(balance.total_balance);
  const referenceTotal = envNumber(qb, `DEEPSEEK_BALANCE_REFERENCE_TOTAL_${currency}`)
    ?? envNumber(qb, "DEEPSEEK_BALANCE_REFERENCE_TOTAL");
  const warningRemaining = envNumber(qb, `DEEPSEEK_BALANCE_WARNING_${currency}`)
    ?? envNumber(qb, "DEEPSEEK_BALANCE_WARNING");
  const used = referenceTotal !== null && remaining !== null ? Math.max(0, referenceTotal - remaining) : null;
  return {
    id: `balance-${dash(currency)}`,
    label: `${currency} balance`,
    remaining,
    used,
    limit: referenceTotal,
    unit: currency,
    warningRemaining,
    resetAt: null,
    resetText: remaining === null ? null : `Balance ${formatMoney(remaining, currency)}`,
    confidence: "exact"
  };
}

function envNumber(qb, name) { return numberOrNull(qb.env.getOptional(name)); }
function numberOrNull(value) {
  if (value === null || value === undefined || value === "") return null;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
}
function textOrNull(value) { const text = String(value || "").trim(); return text || null; }
function dash(value) { return String(value || "unknown").trim().replace(/[^A-Za-z0-9]+/g, "-").replace(/^-+|-+$/g, "").toLowerCase(); }
function formatMoney(value, currency) {
  if (value === null || value === undefined || !Number.isFinite(value)) return `unknown ${currency || ""}`.trim();
  return `${Number.isInteger(value) ? value : value.toFixed(2)} ${currency || ""}`.trim();
}

function main(qb) {
  const now = new Date(qb.now());
  if (!Number.isFinite(now.getTime())) throw new Error("A valid local date is required");
  const minuteMs = 60 * 1000;
  const dayMs = 24 * 60 * minuteMs;
  const tomorrow = startOfNextLocalDay(now);
  const nextMonday = nextLocalWeekStart(now, 1);
  const nextSunday = nextLocalWeekStart(now, 0);
  const nextMonth = new Date(now.getFullYear(), now.getMonth() + 1, 1);
  const nextYear = new Date(now.getFullYear() + 1, 0, 1);
  const snapshot = {
    status: "ok",
    updatedAt: now.toISOString(),
    windows: [
      timeWindow("today", "Today remaining", now, tomorrow, dayMs / minuteMs, "minutes"),
      timeWindow("week-monday", "Week remaining (Monday start)", now, nextMonday, 7 * dayMs / minuteMs, "minutes"),
      timeWindow("week-sunday", "Week remaining (Sunday start)", now, nextSunday, 7 * dayMs / minuteMs, "minutes"),
      timeWindow("month", "Month remaining", now, nextMonth, daysInMonth(now.getFullYear(), now.getMonth()) * dayMs / minuteMs, "minutes"),
      timeWindow("year", "Year remaining", now, nextYear, daysInYear(now.getFullYear()) * dayMs / minuteMs, "minutes")
    ],
    metadata: { providerId: qb.meta.providerId, timezone: qb.timezone(), precision: "minutes" }
  };
  qb.log({ level: "info", stage: "snapshot.ready", message: "Time Flies snapshot ready", windowCount: snapshot.windows.length });
  return snapshot;
}

function timeWindow(id, label, now, resetAt, limit, unit) {
  const remaining = Math.ceil(Math.max(0, resetAt.getTime() - now.getTime()) / (60 * 1000));
  const used = Math.max(0, limit - remaining);
  const remainingPercent = Math.max(0, Math.min(100, remaining / limit * 100));
  return { id, label, remaining, used, limit, unit, usedPercent: 100 - remainingPercent, remainingPercent, resetAt: resetAt.toISOString(), resetText: null, confidence: "exact" };
}
function startOfNextLocalDay(now) { return new Date(now.getFullYear(), now.getMonth(), now.getDate() + 1); }
function nextLocalWeekStart(now, weekStartDay) {
  const daysUntilStart = (weekStartDay - now.getDay() + 7) % 7 || 7;
  return new Date(now.getFullYear(), now.getMonth(), now.getDate() + daysUntilStart);
}
function daysInMonth(year, month) { return new Date(year, month + 1, 0).getDate(); }
function daysInYear(year) { return new Date(year, 11, 31).getDate() === 31 && new Date(year, 1, 29).getDate() === 29 ? 366 : 365; }
